// Offer the next 3 genuinely free 45-minute slots inside site-office hours.
const cfg = $('Config').first().json;
const tz = cfg.TIMEZONE || 'Asia/Kolkata';
const dur = Number(cfg.VISIT_DURATION_MIN || 45);
const startH = Number(cfg.BOOKING_START_HOUR || 10);
const endH = Number(cfg.BOOKING_END_HOUR || 18);
const leadHours = Number(cfg.BOOKING_LEAD_HOURS || 3);
const busy = $input.all()
  .map(i => i.json)
  .filter(e => e && e.start)
  .map(e => ({
    s: DateTime.fromISO(e.start.dateTime || e.start.date, { zone: tz }),
    e: DateTime.fromISO(e.end && (e.end.dateTime || e.end.date) ? (e.end.dateTime || e.end.date) : (e.start.dateTime || e.start.date), { zone: tz })
  }))
  .filter(b => b.s.isValid && b.e.isValid);
const now = DateTime.now().setZone(tz);
const earliest = now.plus({ hours: leadHours });
const slots = [];
for (let d = 0; d <= 7 && slots.length < 3; d++) {
  let cur = now.plus({ days: d }).set({ hour: startH, minute: 0, second: 0, millisecond: 0 });
  while (cur.hour < endH && slots.length < 3) {
    const end = cur.plus({ minutes: dur });
    const clash = busy.some(b => cur < b.e && end > b.s);
    if (!clash && cur > earliest) {
      slots.push({ start: cur.toISO(), end: end.toISO(), label: cur.toFormat('ccc dd LLL, HH:mm') });
    }
    cur = cur.plus({ minutes: dur + 15 });
  }
}
if (!slots.length) {
  const f = now.plus({ days: 1 }).set({ hour: startH + 1, minute: 0, second: 0, millisecond: 0 });
  slots.push({ start: f.toISO(), end: f.plus({ minutes: dur }).toISO(), label: f.toFormat('ccc dd LLL, HH:mm') });
}
const c = $('Build Context').first().json;
return [{ json: {
  slots,
  prompt: 'Great! Site visits for *' + c.project + '* run ' + startH + ':00 to ' + endH + ':00 IST and take about ' + dur + ' minutes.\n\nPick a slot that works for you:'
} }];

