// Attach the grade to the lead. Never lose a lead because the model call failed.
const lead = $('Flag Duplicate').first().json;
const blocks = Array.isArray($json.content) ? $json.content : [];
const text = blocks.filter(b => b.type === 'text').map(b => b.text).join('').trim();
let ai = null;
if ($json.stop_reason !== 'refusal' && text) { try { ai = JSON.parse(text); } catch (e) { ai = null; } }
if (!ai) {
  ai = { score: 50, grade: 'WARM', is_timepass: false, is_broker: false, budget_band: lead.budget || 'Unknown',
    configuration: lead.configuration || 'Unknown', timeline: 'Unknown', funding: 'Unknown',
    intent_signals: [], risk_flags: ['ai_grading_unavailable'], next_action: 'Manual review - automatic grading did not run',
    summary: 'Ungraded enquiry, treat as warm until a human looks at it' };
}
if (ai.is_timepass) ai.grade = 'JUNK';
return [{ json: {
  ...lead,
  grade: ai.grade,
  score: ai.score,
  is_timepass: !!ai.is_timepass,
  is_broker: !!ai.is_broker,
  budget: lead.budget || ai.budget_band,
  budget_band: ai.budget_band,
  configuration: lead.configuration || ai.configuration,
  timeline: lead.timeline || ai.timeline,
  funding: ai.funding,
  intent_signals: (ai.intent_signals || []).join(', '),
  risk_flags: (ai.risk_flags || []).join(', '),
  next_action: ai.next_action,
  ai_summary: ai.summary,
  followup_count: 0
} }];

